import { useEffect, useId, useRef } from "react";
import "./ConfirmDialog.css";

export interface ConfirmDialogProps {
  open: boolean;
  noteTitle: string;
  onCancel: () => void;
  onConfirm: () => void;
}

const BUTTON_SELECTOR = "button:not([disabled])";

export function ConfirmDialog({
  open,
  noteTitle,
  onCancel,
  onConfirm,
}: ConfirmDialogProps) {
  const titleId = useId();
  const descriptionId = useId();
  const dialogRef = useRef<HTMLDivElement>(null);
  const cancelRef = useRef<HTMLButtonElement>(null);

  // Move focus into the dialog on open, on Cancel (the safe choice for a
  // destructive action), and return focus to the opener on close.
  useEffect(() => {
    if (!open) return;

    const opener =
      document.activeElement instanceof HTMLElement
        ? document.activeElement
        : null;

    cancelRef.current?.focus();

    return () => {
      opener?.focus();
    };
  }, [open]);

  // Escape cancels. Tab and Shift+Tab stay inside the dialog.
  useEffect(() => {
    if (!open) return;

    function handleKeyDown(event: KeyboardEvent) {
      if (event.key === "Escape") {
        event.preventDefault();
        onCancel();
        return;
      }

      const dialog = dialogRef.current;
      if (event.key !== "Tab" || dialog === null) return;

      const buttons = Array.from(
        dialog.querySelectorAll<HTMLButtonElement>(BUTTON_SELECTOR),
      );
      const first = buttons[0];
      const last = buttons[buttons.length - 1];
      if (first === undefined || last === undefined) return;

      const active = document.activeElement;
      const focusIsInside = active !== null && dialog.contains(active);

      if (event.shiftKey && (!focusIsInside || active === first)) {
        event.preventDefault();
        last.focus();
      } else if (!event.shiftKey && (!focusIsInside || active === last)) {
        event.preventDefault();
        first.focus();
      }
    }

    document.addEventListener("keydown", handleKeyDown);
    return () => {
      document.removeEventListener("keydown", handleKeyDown);
    };
  }, [open, onCancel]);

  if (!open) return null;

  return (
    <div className="confirm-dialog-backdrop">
      <div
        ref={dialogRef}
        className="confirm-dialog"
        role="alertdialog"
        aria-modal="true"
        aria-labelledby={titleId}
        aria-describedby={descriptionId}
      >
        <h2 id={titleId} className="confirm-dialog__title">
          Delete this note?
        </h2>
        <p id={descriptionId} className="confirm-dialog__body">
          &ldquo;{noteTitle}&rdquo; will be removed. This cannot be undone.
        </p>
        <div className="confirm-dialog__actions">
          <button
            ref={cancelRef}
            type="button"
            className="confirm-dialog__button"
            onClick={onCancel}
          >
            Cancel
          </button>
          <button
            type="button"
            className="confirm-dialog__button confirm-dialog__button--primary"
            onClick={onConfirm}
          >
            Delete
          </button>
        </div>
      </div>
    </div>
  );
}
