.confirm-dialog-backdrop {
  position: fixed;
  inset: 0;
  z-index: 1000;
  display: grid;
  place-items: center;
  padding: clamp(16px, 4vw, 32px);
  background: color-mix(in srgb, var(--slide) 72%, transparent);
}

.confirm-dialog {
  width: min(100%, 26rem);
  display: grid;
  gap: clamp(10px, 2vw, 14px);
  padding: clamp(18px, 3vw, 24px);
  border: 1px solid var(--hair);
  border-radius: 14px;
  background: var(--slide);
  color: var(--ink);
  font: inherit;
}

.confirm-dialog__title {
  margin: 0;
  font: inherit;
  font-size: clamp(1.05rem, 2.4vw, 1.3rem);
  font-weight: 600;
  color: var(--ink);
}

.confirm-dialog__body {
  margin: 0;
  font: inherit;
  font-size: clamp(0.9rem, 1.9vw, 1rem);
  line-height: 1.5;
  color: var(--muted);
  overflow-wrap: anywhere;
}

.confirm-dialog__actions {
  display: flex;
  flex-wrap: wrap;
  justify-content: flex-end;
  gap: 10px;
  margin-top: 6px;
}

.confirm-dialog__button {
  font: inherit;
  font-size: clamp(0.9rem, 1.9vw, 1rem);
  font-weight: 500;
  min-height: 44px;
  padding: 8px 20px;
  border: 1px solid var(--ink);
  border-radius: 999px;
  background: transparent;
  color: var(--ink);
  cursor: pointer;
}

.confirm-dialog__button:hover {
  background: var(--myelin-wash);
}

.confirm-dialog__button--primary {
  border-color: var(--myelin);
  background: var(--myelin);
  color: var(--slide);
}

.confirm-dialog__button--primary:hover {
  background: var(--myelin);
  filter: brightness(1.08);
}

@media (prefers-reduced-motion: no-preference) {
  :root:not([data-motion="reduce"]) .confirm-dialog-backdrop {
    animation: confirm-dialog-fade 160ms ease-out;
  }

  :root:not([data-motion="reduce"]) .confirm-dialog {
    animation: confirm-dialog-rise 200ms ease-out;
  }

  :root:not([data-motion="reduce"]) .confirm-dialog__button {
    transition: background-color 120ms ease;
  }
}

@keyframes confirm-dialog-fade {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}

@keyframes confirm-dialog-rise {
  from {
    opacity: 0;
    transform: translateY(8px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}
